#!/usr/bin/env python3
"""Generate bridge/ffmpeg-demux-enum-map.h from the two FFmpeg header trees.

libavcodec/libavutil renumber some public enums across major versions
(AVCodecID and AVPixelFormat both moved between 4.4.x and 9.0.2). The demux
shim copies those enum-valued AVCodecParameters fields into the app's 4.4.x
shaped shadow, so each value must be translated back or the app looks up the
wrong decoder or pixel format.

The table is produced by compiling a name probe against both header trees and
diffing; nothing is hard-coded from memory.
"""

import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LEGACY_INCLUDE = ROOT / "build/deps/ffmpeg-core/include"
MODERN_INCLUDE = ROOT / "build/deps/ffmpeg-demux/include"
OUTPUT = ROOT / "bridge/ffmpeg-demux-enum-map.h"


def enum_body(text: str, enum: str) -> str:
    """Return the body of `enum <enum>`, comment- and brace-aware."""

    start = text.index("enum " + enum)
    i = text.index("{", start) + 1
    depth = 1
    j = i
    while j < len(text) and depth:
        if text.startswith("//", j):
            j = text.index("\n", j)
        elif text.startswith("/*", j):
            j = text.index("*/", j) + 2
        elif text[j] == "{":
            depth += 1
            j += 1
        elif text[j] == "}":
            depth -= 1
            j += 1
        else:
            j += 1
    return text[i : j - 1]


def enum_names(header: Path, enum: str, prefix: str) -> list[str]:
    text = header.read_text(encoding="utf-8", errors="ignore")
    return sorted({match for match in re.findall(rf"\b({prefix}[A-Za-z0-9_]*)\b", enum_body(text, enum))})


def probe(names: list[str], include: Path) -> dict[str, int]:
    lines = [
        "#include <stdio.h>",
        "#include <libavcodec/avcodec.h>",
        "#include <libavutil/pixfmt.h>",
        "int main(void){",
    ]
    lines += [f'printf("{name} %d\\n", (int){name});' for name in names]
    lines.append("return 0;}")
    with tempfile.TemporaryDirectory() as work:
        work = Path(work)
        source = work / "probe.c"
        binary = work / "probe"
        source.write_text("\n".join(lines), encoding="utf-8")
        subprocess.run(["clang", "-I", str(include), str(source), "-o", str(binary)], check=True)
        out = subprocess.run([str(binary)], check=True, capture_output=True, text=True).stdout
    return {name: int(value) for name, value in (line.split() for line in out.splitlines())}


def build_table(legacy: dict[str, int], modern: dict[str, int], missing: int) -> list[tuple[int, int]]:
    """Map every modern value to its 4.4.x value, by enum name.

    A value that the 4.4.x enum does not name maps to the neutral codec/format.
    When several modern names share a value (aliases), a name that exists in
    4.4.x wins over one that does not, so a real mapping is never shadowed.
    """

    table: dict[int, int] = {}
    for name, modern_value in modern.items():
        legacy_value = legacy.get(name)
        if legacy_value is None:
            table.setdefault(modern_value, missing)
        elif legacy_value != modern_value:
            table[modern_value] = legacy_value
    return sorted(table.items())


def table(name: str, entries: list[tuple[int, int]]) -> str:
    rows = "\n".join(f"    {{ {modern}, {legacy} }}," for modern, legacy in entries)
    return f"static const npa_enum_map_entry {name}[] = {{\n{rows}\n}};\n"


def main() -> int:
    codec_header = "libavcodec/codec_id.h"
    pix_header = "libavutil/pixfmt.h"
    legacy_codec_names = enum_names(LEGACY_INCLUDE / codec_header, "AVCodecID", "AV_CODEC_ID_")
    modern_codec_names = enum_names(MODERN_INCLUDE / codec_header, "AVCodecID", "AV_CODEC_ID_")
    legacy_pix_names = enum_names(LEGACY_INCLUDE / pix_header, "AVPixelFormat", "AV_PIX_FMT_")
    modern_pix_names = enum_names(MODERN_INCLUDE / pix_header, "AVPixelFormat", "AV_PIX_FMT_")
    # AV_PIX_FMT_NE is a macro used to build names, not an enum constant.
    legacy_pix_names = [name for name in legacy_pix_names if name != "AV_PIX_FMT_NE"]
    modern_pix_names = [name for name in modern_pix_names if name != "AV_PIX_FMT_NE"]

    codec = table("npa_codec_id_map", build_table(
        probe(legacy_codec_names, LEGACY_INCLUDE), probe(modern_codec_names, MODERN_INCLUDE), 0))
    pix = table("npa_pix_fmt_map", build_table(
        probe(legacy_pix_names, LEGACY_INCLUDE), probe(modern_pix_names, MODERN_INCLUDE), -1))

    OUTPUT.write_text(
        "\n".join(
            [
                "/*",
                " * Generated by deps/gen_demux_enum_map.py - do not edit by hand.",
                " *",
                " * libavcodec/libavutil renumber AVCodecID and AVPixelFormat across major",
                " * versions. The demux shim copies those fields into the app's 4.4.x shaped",
                " * shadow, so each value is translated back here. A value with no 4.4.x",
                " * equivalent maps to the neutral codec/format so the app never matches a",
                " * different codec or pixel format by accident.",
                " */",
                "",
                "#ifndef NPA_FFMPEG_DEMUX_ENUM_MAP_H",
                "#define NPA_FFMPEG_DEMUX_ENUM_MAP_H",
                "",
                "typedef struct npa_enum_map_entry {",
                "    int modern;",
                "    int legacy;",
                "} npa_enum_map_entry;",
                "",
                codec,
                pix,
                "static inline int npa_enum_lookup(const npa_enum_map_entry *table, unsigned count, int value)",
                "{",
                "    unsigned i;",
                "",
                "    for (i = 0; i < count; i++)",
                "        if (table[i].modern == value)",
                "            return table[i].legacy;",
                "    return value;",
                "}",
                "",
                "static inline int npa_codec_id_to_legacy(int codec_id)",
                "{",
                "    return npa_enum_lookup(npa_codec_id_map,",
                "                           sizeof(npa_codec_id_map) / sizeof(npa_codec_id_map[0]),",
                "                           codec_id);",
                "}",
                "",
                "static inline int npa_pix_fmt_to_legacy(int pix_fmt)",
                "{",
                "    return npa_enum_lookup(npa_pix_fmt_map,",
                "                           sizeof(npa_pix_fmt_map) / sizeof(npa_pix_fmt_map[0]),",
                "                           pix_fmt);",
                "}",
                "",
                "#endif /* NPA_FFMPEG_DEMUX_ENUM_MAP_H */",
                "",
            ]
        ),
        encoding="utf-8",
    )
    print(f"wrote {OUTPUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
